//! Fixed PPR-00 latency statistics and client/server reconciliation contracts.
use serde_json::{Value,json};
use crate::canonical::sha256;
pub const COMPONENTS:[&str;5]=["local_pre_provider_seconds","provider_wait_seconds","local_projection_seconds","local_overhead_seconds","model_plane_ttft_seconds"];
fn rounded(v:f64,places:i32)->f64{let factor=10f64.powi(places);(v*factor).round_ties_even()/factor}
pub fn timing_line(line:&str)->Option<Value>{let pattern=regex::Regex::new(r"Agent model-plane timing schema=ppr-timing/v1 wire=(\S+) run_id=(\S+) call_id=(\S+) model=(\S+) (.*)$").unwrap();let m=pattern.captures(line)?;let mut result=json!({"wire":&m[1],"run_id_sha256":sha256(m[2].as_bytes()),"call_id":&m[3],"model":&m[4]});for key in COMPONENTS{result[key]=Value::Null;}let pairs=regex::Regex::new(r"(\w+_seconds)=(-?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?)").unwrap();for pair in pairs.captures_iter(&m[5]){if COMPONENTS.contains(&&pair[1]){result[&pair[1]]=json!(pair[2].parse::<f64>().ok());}}Some(result)}
pub fn reconcile(record:&Value,client:Option<f64>)->Value{let server=record["model_plane_ttft_seconds"].as_f64();let parts=COMPONENTS[..3].iter().map(|k|record[k].as_f64()).collect::<Option<Vec<_>>>();let(Some(server),Some(client),Some(parts))=(server,client,parts)else{return json!({"status":"incomplete","server":record})};let identity=(parts.iter().sum::<f64>()-server).abs();if identity>0.005{return json!({"status":"identity_violation","server":record,"identity_residual_seconds":rounded(identity,9),"identity_tolerance_seconds":0.005})}let residual=client-server;let tolerance=0.200f64.max(0.05*client);json!({"status":if residual>=-0.010&&residual<=tolerance{"ok"}else{"tolerance_exceeded"},"server":record,"residual_seconds":rounded(residual,6),"identity_residual_seconds":rounded(identity,9),"tolerance_seconds":rounded(tolerance,6),"lower_bound_seconds":0.010})}
pub fn percentile(values:&[f64],percentile:f64)->Option<f64>{if values.is_empty(){return None}let mut ordered=values.to_vec();ordered.sort_by(f64::total_cmp);let rank=(percentile*ordered.len()as f64).ceil().max(1.)as usize;ordered.get(rank-1).map(|v|rounded(*v,6))}
pub fn iqr(values:&[f64])->Option<f64>{Some(rounded(percentile(values,0.75)?-percentile(values,0.25)?,6))}
pub fn bootstrap(values:&[f64],quantile:f64)->Value{if values.is_empty(){return json!({"low":null,"high":null})}let mut rng=crate::bootstrap::Random::new(0);let mut draws=vec![];for _ in 0..2000{let sample=(0..values.len()).map(|_|{let a=(rng.next()>>5)as u64;let b=(rng.next()>>6)as u64;let random=((a<<26)+b)as f64/9007199254740992.;values[(random*values.len()as f64).floor()as usize]}).collect::<Vec<_>>();draws.push(percentile(&sample,quantile).unwrap_or(0.));}draws.sort_by(f64::total_cmp);json!({"low":draws[50],"high":draws[1949]})}
pub fn metric_summary(values:&[f64])->Value{json!({"p50":percentile(values,0.50),"p95":percentile(values,0.95),"min":values.iter().copied().reduce(f64::min).map(|v|rounded(v,6)),"max":values.iter().copied().reduce(f64::max).map(|v|rounded(v,6))})}
pub fn certification(trials:&[Value],reader_present:bool,gate_size:usize,passed:bool)->Value{let records=trials.iter().filter_map(|t|t["timing_reconciliation"].as_object().map(|_|&t["timing_reconciliation"])).collect::<Vec<_>>();let collected=records.len()==trials.len()&&records.iter().all(|r|["ok","tolerance_exceeded"].contains(&r["status"].as_str().unwrap_or("")));let residuals=records.iter().filter_map(|r|r["residual_seconds"].as_f64()).collect::<Vec<_>>();let lower=residuals.len()==records.len()&&residuals.iter().all(|v|*v>=-0.010);let abs=residuals.iter().map(|v|v.abs()).collect::<Vec<_>>();let p99=percentile(&abs,0.99);let p99_ok=p99.filter(|v|*v!=0.).unwrap_or(1.)<=0.250;let ceiling=abs.iter().copied().reduce(f64::max);let ceiling_ok=ceiling.is_some_and(|v|v<=0.500);let reconciliation=reader_present.then_some(collected&&lower&&p99_ok&&ceiling_ok);json!({"recordable":passed&&reconciliation==Some(true)&&gate_size>=100,"reconciliation_passed":reconciliation,"gate_set_meets_recordable_min":gate_size>=100,"all_trials_abs_residual_p99_seconds":if reader_present{p99}else{None},"all_trials_abs_residual_max_seconds":if reader_present{ceiling.map(|v|rounded(v,6))}else{None}})}
#[cfg(test)]mod tests{use super::*;#[test]fn small_exploration_cannot_self_certify(){let trial=json!({"timing_reconciliation":{"status":"ok","residual_seconds":0.1}});assert_eq!(certification(&[trial],true,1,true)["recordable"],false);}#[test]fn server_identity_and_lower_bound_fail_closed(){let record=json!({"local_pre_provider_seconds":0.1,"provider_wait_seconds":0.2,"local_projection_seconds":0.1,"model_plane_ttft_seconds":0.4});assert_eq!(reconcile(&record,Some(0.5))["status"],"ok");assert_eq!(reconcile(&record,Some(0.3))["status"],"tolerance_exceeded");let mut broken=record;broken["model_plane_ttft_seconds"]=json!(0.3);assert_eq!(reconcile(&broken,Some(0.5))["status"],"identity_violation");}#[test]fn nearest_rank_and_empty_bootstrap(){assert_eq!(percentile(&[4.,1.,3.,2.],0.5),Some(2.));assert_eq!(bootstrap(&[],0.5),json!({"low":null,"high":null}));}}
